.pks3-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pks3-root,.pks3-root *,.pks3-root *::before,.pks3-root *::after{box-sizing:border-box}
.pks3-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pks3-root img{display:block;border:0;max-width:none}
.pks3-root [hidden]{display:none!important}
.pks3-root .nS3_1_9912{align-content:stretch;display:flex;flex:1 0 0;gap:2px;align-items:center;min-width:1px;position:relative}
